@page "/settings"
@using sv_5d588b717aed416aa505a98fb2865599.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2 class="sidebar-title">Settings</h2>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span class="nav-label">@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastType)">
                @_toastMessage
            </div>
        }
    </main>
</div>

@* ───── Confirmation Dialog ───── *@
@if (_showConfirmDialog)
{
    <div class="dialog-overlay" @onclick="CancelConfirm">
        <div class="dialog" @onclick:stopPropagation="true">
            <h3>@_confirmTitle</h3>
            <p>@_confirmMessage</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
            </div>
        </div>
    </div>
}

@code {
    // ───── Section navigation ─────
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨"),
    };

    // ───── Toast ─────
    private string? _toastMessage;
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    // ───── Profile state ─────
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;

    // ───── Notifications state ─────
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<(string Channel, bool Muted)> _channels = new();

    // ───── Security state ─────
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    // ───── Appearance state ─────
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _availableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Portuguese" };

    // ───── Confirmation dialog ─────
    private bool _showConfirmDialog;
    private string _confirmTitle = "";
    private string _confirmMessage = "";
    private Func<Task>? _confirmCallback;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _channels = notif.MutedChannels.Select(c => (c, true)).ToList();

        var security = securityTask.Result;
        _twoFactorEnabled = security.TwoFactorEnabled;
        _lastPasswordChange = security.LastPasswordChange;
        _sessions = security.Sessions;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    // ───── Toast helpers ─────
    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, _toastCts.Token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // ───── Profile actions ─────
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            _displayName = _savedProfile.DisplayName;
            _email = _savedProfile.Email;
            _avatarUrl = _savedProfile.AvatarUrl;
            _bio = _savedProfile.Bio;
        }
    }

    // ───── Notifications actions ─────
    private void ToggleChannel(int index)
    {
        var (channel, muted) = _channels[index];
        _channels[index] = (channel, !muted);
    }

    private async Task SaveNotificationPrefs()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Channel).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ───── Security actions ─────
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _lastPasswordChange = DateTime.UtcNow;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _confirmTitle = "Revoke Session";
        _confirmMessage = $"Are you sure you want to revoke the session on \"{session.Device}\" in {session.Location}?";
        _confirmCallback = async () => await RevokeSession(session.Id);
        _showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
        await ShowToast("Session revoked.");
    }

    private void ToggleTwoFactor(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
    }

    // ───── Appearance actions ─────
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // ───── Confirmation dialog ─────
    private async Task ConfirmAction()
    {
        _showConfirmDialog = false;
        if (_confirmCallback is not null)
        {
            await _confirmCallback();
        }
    }

    private void CancelConfirm()
    {
        _showConfirmDialog = false;
    }

    // ───── Render fragments ─────
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" />
                </div>
                <span class="avatar-url">@_avatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_bio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @for (int i = 0; i < _channels.Count; i++)
                {
                    var index = i;
                    <label class="channel-item">
                        <input type="checkbox" checked="@_channels[index].Muted" @onchange="() => ToggleChannel(index)" />
                        <span>#@_channels[index].Channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
